I have watched countless checkout flows fail in production. My eyes have witnessed cart abandonments, payment failures, and security breaches that haunt developers' dreams. Here is the test suite my vigilance demands.

```typescript
// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock providers - fifty eyes verify these are properly isolated
const mockCartContext = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};

const mockPaymentContext = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCartContext,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => mockPaymentContext,
}));

const validShipping = {
  street: '123 Main St',
  city: 'Springfield',
  state: 'CA',
  zip: '90210',
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'John Doe',
};

describe('Checkout - Happy Path', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockPaymentContext.processPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), validShipping.street);
    await user.type(screen.getByLabelText(/city/i), validShipping.city);
    await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
    await user.type(screen.getByLabelText(/zip code/i), validShipping.zip);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
    await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
    await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
    await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/widget/i)).toBeInTheDocument();
    expect(screen.getByText(/\$29\.99/)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    expect(await screen.findByRole('status')).toHaveTextContent(/ORD-12345/);
    expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    expect(mockCartContext.clearCart).toHaveBeenCalled();
  });
});

describe('Checkout - Form Validation', () => {
  it('displays shipping validation errors for empty fields', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByText(/city is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });

  it('rejects invalid card number', async () => {
    const user = userEvent.setup();
    render(<Checkout />);
    // Navigate to payment step first
    await fillShippingForm(user, validShipping);

    await user.type(screen.getByLabelText(/card number/i), '1234');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error States', () => {
  it('displays payment failure and allows retry', async () => {
    mockPaymentContext.processPayment.mockRejectedValueOnce(new Error('Card declined'));
    const user = userEvent.setup();
    render(<Checkout />);

    await completeToReviewStep(user);
    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Loading States', () => {
  it('disables buttons and shows loading indicator during submission', async () => {
    mockPaymentContext.processPayment.mockImplementation(
      () => new Promise(resolve => setTimeout(() => resolve({ orderId: 'ORD-1' }), 100))
    );
    const user = userEvent.setup();
    render(<Checkout />);

    await completeToReviewStep(user);
    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    mockCartContext.items = [];
    render(<Checkout onCancel={vi.fn()} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
  });
});

describe('Checkout - Accessibility', () => {
  it('has no accessibility violations on shipping step', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });

  it('announces step changes to screen readers', () => {
    render(<Checkout />);
    const nav = screen.getByRole('navigation', { name: /checkout progress/i });
    expect(within(nav).getByText('Shipping')).toHaveAttribute('aria-current', 'step');
  });
});

// Helper functions
async function fillShippingForm(user, data) {
  await user.type(screen.getByLabelText(/street address/i), data.street);
  await user.type(screen.getByLabelText(/city/i), data.city);
  await user.selectOptions(screen.getByLabelText(/state/i), data.state);
  await user.type(screen.getByLabelText(/zip code/i), data.zip);
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function completeToReviewStep(user) {
  await fillShippingForm(user, validShipping);
  await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
  await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
  await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
  await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
